CREATE TABLE v2_schema_metadata(owner TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version=1), digest TEXT NOT NULL) STRICT;
CREATE TABLE runtime_instances(id TEXT PRIMARY KEY, started_at TEXT NOT NULL, ended_at TEXT) STRICT;
CREATE TABLE runtime_leases(resource TEXT PRIMARY KEY, runtime_id TEXT NOT NULL REFERENCES runtime_instances(id), expires_at TEXT NOT NULL) STRICT;
CREATE TABLE events(sequence INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL UNIQUE, owner TEXT NOT NULL, kind TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), payload TEXT NOT NULL CHECK(json_valid(payload)), created_at TEXT NOT NULL) STRICT;
CREATE INDEX events_owner ON events(owner,sequence);
CREATE TRIGGER immutable_event_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'immutable audit event'); END;
CREATE TRIGGER immutable_event_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'immutable audit event'); END;
CREATE TABLE projection_revisions(topic TEXT PRIMARY KEY, revision INTEGER NOT NULL CHECK(revision>0)) STRICT;
CREATE TABLE projection_outbox(sequence INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL REFERENCES events(event_id), topic TEXT NOT NULL, revision INTEGER NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), acknowledged_at TEXT, UNIQUE(topic,revision)) STRICT;
CREATE TABLE artifact_objects(hash TEXT PRIMARY KEY, byte_length INTEGER NOT NULL CHECK(byte_length>=0), bytes BLOB NOT NULL CHECK(length(bytes)=byte_length)) STRICT;
CREATE TABLE artifacts(id TEXT PRIMARY KEY, object_hash TEXT NOT NULL REFERENCES artifact_objects(hash), media_type TEXT NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE TABLE artifact_owners(artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE, owner TEXT NOT NULL, PRIMARY KEY(artifact_id,owner)) STRICT;
CREATE TABLE artifact_access_links(artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE, subject TEXT NOT NULL, PRIMARY KEY(artifact_id,subject)) STRICT;
CREATE TABLE artifact_gc_queue(artifact_id TEXT PRIMARY KEY REFERENCES artifacts(id) ON DELETE CASCADE) STRICT;
CREATE TABLE operations(id TEXT PRIMARY KEY, domain TEXT NOT NULL, kind TEXT NOT NULL, content_hash TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), payload TEXT NOT NULL CHECK(json_valid(payload)), revision INTEGER NOT NULL CHECK(revision>0), state TEXT NOT NULL CHECK(state IN('prepared','running','waiting_external','cancel_requested','succeeded','failed','cancelled','unknown')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE operation_journal_entries(operation_id TEXT NOT NULL REFERENCES operations(id), ordinal INTEGER NOT NULL CHECK(ordinal>0), kind TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at TEXT NOT NULL, PRIMARY KEY(operation_id,ordinal)) STRICT;
CREATE TABLE operation_idempotency(domain TEXT NOT NULL, request_key TEXT NOT NULL, content_hash TEXT NOT NULL, operation_id TEXT NOT NULL UNIQUE REFERENCES operations(id), PRIMARY KEY(domain,request_key)) STRICT;
CREATE TABLE operation_leases(operation_id TEXT PRIMARY KEY REFERENCES operations(id), owner TEXT NOT NULL, generation INTEGER NOT NULL CHECK(generation>0), expires_at TEXT NOT NULL) STRICT;
CREATE TABLE operation_artifact_links(operation_id TEXT NOT NULL REFERENCES operations(id), artifact_id TEXT NOT NULL REFERENCES artifacts(id), purpose TEXT NOT NULL, PRIMARY KEY(operation_id,artifact_id,purpose)) STRICT;
CREATE TABLE import_batches(source_hash TEXT PRIMARY KEY, report TEXT NOT NULL CHECK(json_valid(report)), file_manifest TEXT NOT NULL CHECK(json_valid(file_manifest)), completed_at TEXT NOT NULL) STRICT;
CREATE TABLE import_items(source_hash TEXT NOT NULL REFERENCES import_batches(source_hash), kind TEXT NOT NULL, source_key TEXT NOT NULL, content_hash TEXT NOT NULL, disposition TEXT NOT NULL, PRIMARY KEY(source_hash,kind,source_key)) STRICT;
